('songs','s014','{"n": 140, "day": "sexta", "group": "Pout-pourri Salmo 100", "title": "Autoridade e poder", "st": [[{"r": [{"t": "NÃO DÁ!", "v": "t"}, {"t": " Não dá sem Jesus não dá ", "v": "m"}, {"t": "(Oh oh não dá) ", "v": "h"}, {"t": "(4x) ", "v": "m"}, {"t": "(BIS)", "v": "t"}], "c": [[8, "D"], [10, "Bm"], [13, "G"], [15, "Em"], [19, "A"]]}, {"r": [{"t": "Os que confiam no Senhor, são como os montes de Sião, que não se abalam, mas que permanecem para sempre. Como em volta de Jerusalém ", "v": "t"}, {"t": "estão os montes", "v": "h"}, {"t": " Assim o Senhor em volta do seu povo. Autoridade e poder, ", "v": "t"}, {"t": "o domínio em suas mãos.", "v": "h"}, {"t": " Pois o Senhor é Deus, o Senhor é rei dos povos. Calem-se diante dele a terra. Dobre os joelhos↓, ergam as mãos, pois o Senhor é Deus, o Senhor é Rei dos povos.", "v": "t"}]}, {"r": [{"t": "Não dá sem Jesus não dá ", "v": "m"}, {"t": "(Oh oh não dá)", "v": "h"}, {"t": " (4x) (BIS)", "v": "m"}]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
('songs','s015','{"n": 150, "day": "sexta", "group": "Pout-pourri Salmo 100", "title": "Jesus é bom à beça", "st": [[{"r": [{"t": "Na minha vida", "v": "m"}, {"t": " (o que?)", "v": "h"}, {"t": " houve uma mudança linda, sem a dor eu conheci o verdadeiro amor. ", "v": "m"}, {"t": "Na minha vida ", "v": "h"}, {"t": "(2x)", "v": "m"}], "c": [[0, "D"], [25, "G"], [37, "A"], [45, "D"], [65, "G"], [77, "A"], [83, "D"]]}], [{"r": [{"t": "Agora se, se, se vejo alguém sem paz no coração / pedindo a minha ajuda, eu logo lhe estendo a mão (2x)", "v": "t"}], "c": [[7, "G"], [25, "A"], [33, "F#m"], [44, "Bm"], [52, "G"], [68, "A"], [78, "G"], [90, "A"], [96, "D"]]}], [{"r": [{"t": "Hoje eu te amo,", "v": "h"}, {"t": " Hoje eu te amo,", "v": "m"}, {"t": " (porque)", "v": "h"}, {"t": " porque Jesus me amou primeiro. Entre nessa eu te garanto que ele é bom a beça.(2x)", "v": "m"}]}, {"r": [{"t": "Agora se, se, se vejo alguém sem paz no coração / pedindo a minha ajuda, logo lhe estendo a mão (2x)", "v": "t"}]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
('songs','s016','{"n": 160, "day": "sexta", "group": "", "title": "Criatura criador", "st": [[{"r": [{"t": "Oh, Deus do céu e da luz o teu amor é festa em mim", "v": "h"}, {"t": " (Tchuru tchuru tchuru tchuru) ", "v": "m"}, {"t": "Um palmo deste chão Em qualquer direção eu digo sim. Digo que uma coisa quase incontrolável bate aqui", "v": "h"}, {"t": "(Tchuru tchuru tchuru tchuru) ", "v": "m"}, {"t": "Dispara o coração, não tem explicação, só sei sentir… IôIôIôIôIô êo Iê ô", "v": "h"}, {"t": " (Iêêêêêôôôôô) ", "v": "m"}, {"t": "IêIêIêIêIê IôIôIôêô", "v": "t"}], "c": [[0, "C"], [1, "Dm"], [5, "G"], [7, "C"], [9, "G"]]}], [{"r": [{"t": "SAÚDO! Saúdo a feliz diferença", "v": "h"}, {"t": " (Uuuu) ", "v": "m"}, {"t": "Do irmão de outra raça e crença", "v": "h"}, {"t": " (Uuuuaaaa) ", "v": "m"}, {"t": "Assim como eu tantos filhos de Deus ", "v": "h"}, {"t": "(Tantos filhos de Deus) ", "v": "m"}, {"t": "Convido a todos para essa festa", "v": "h"}, {"t": " (Uuuu) ", "v": "m"}, {"t": "O amor é tudo que nos resta", "v": "h"}, {"t": " (Uuuu)", "v": "m"}, {"t": " Criador não tem raça nem religião.", "v": "h"}], "pre": ["Dm C Dm C G (2x)"]}, {"r": [{"t": "Tá no coração", "v": "h"}, {"t": " Branco, negros, pardos e orientais. ", "v": "m"}, {"t": "Tudo criatura, criador. Hindus, judeus, ateus, cristãos e tudo mais!", "v": "h"}, {"t": " (Para tua glória Senhor) ", "v": "m"}, {"t": "O sol brilhando aqui, A lua em Calcutá", "v": "h"}, {"t": " (Maravilhas do amor) ", "v": "m"}, {"t": "Alguém daqui, Berlim, Pequim qualquer lugar ", "v": "h"}, {"t": "(Frutos da mesma luz).", "v": "m"}], "pre": ["Refrão: C Dm (4x) G"]}, {"r": [{"t": "Então mais uma vez Oh, Deus do amor que habita em mim ", "v": "h"}, {"t": "(Tchuru tchuru tchuru tchuru) ", "v": "m"}, {"t": "Escutai minha canção, não grande oração, mas mesmo assim. Eu peço, não por mim, mas pelo mundo inteiro enfim ", "v": "h"}, {"t": "(Tchuru tchuru tchuru tchuru) ", "v": "m"}, {"t": "Iluminai a terra e a alma dessa gente até o fim. IôIôI