('songs','s021','{"n": 210, "day": "sabado", "group": "Trânsito", "title": "Animais", "st": [[{"r": [{"t": "Lá vem o crocodilo, o orangotango, as duas serpentinhas, a águia real, o gato, o rato… Não faltou ninguém! Só não se via os dois pequinês.", "v": "t"}]}], [{"r": [{"t": "Repetir a música várias vezes. A cada vez, tira-se um animal: no lugar do nome dele, faz-se só a dancinha, sem cantar.", "v": "i"}]}, {"r": [{"t": "Ex.: na 2ª vez, “Lá vem o… (dancinha do crocodilo) orangotango…”. Vai tirando todos os animais até acabar a música.", "v": "i"}]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
