('songs','s040','{"n": 400, "day": "sabado", "group": "", "title": "Água viva", "st": [[{"r": [{"t": "Existe um canteiro muito lindo ", "v": "t"}, {"t": "(ôôô)", "v": "h"}, {"t": " de flores preciosas de valor. Regado porum rio cristalino, uma fonte que jamaisse esgotou. Uma fonte que emana lá do alto ", "v": "t"}, {"t": "(ôôô)", "v": "h"}, {"t": " um mistério que jamais se revelou. O canteiro é a igreja reunida. As flores são os servos do Senhor. ", "v": "t"}, {"t": "(água viva).", "v": "h"}, {"t": "Água viva, que jorra dos céus, uma fonteque transborda no meu ser ", "v": "t"}, {"t": "(água viva.)", "v": "h"}, {"t": "Água viva, que jorra de Deus. Enche-me, enche-me,sacia-me.", "v": "t"}], "c": [[5, "C"], [37, "Am"], [47, "Em"], [76, "F"], [97, "C"], [114, "D"], [152, "G"], [278, "C"], [283, "Em"], [293, "Am"], [306, "Em"], [317, "F"], [353, "G"], [356, "C"], [364, "Em"], [375, "Am"], [386, "Em"], [393, "F"], [402, "G"], [412, "(G)"], [412, "C"]], "pre": ["C Am Em F C D G (2x)"]}], [{"r": [{"t": "Jesus nesse jardim é o jardineiro ", "v": "t"}, {"t": "(ôôô)", "v": "h"}, {"t": " que rega todas flores com amor. A água ela corre noite e dia, no canteiro que o Senhor já preparou. A água está correndo, ela não para ", "v": "t"}, {"t": "(ôôô)", "v": "h"}, {"t": " se você é uma flor deve sentir. Se estás sedenta fala ao jardineiro Ele está passando por aqui.", "v": "t"}, {"t": "(água viva).", "v": "h"}]}, {"r": [{"t": "Água viva, que jorra dos céus, uma fonte que transborda no meu ser ", "v": "t"}, {"t": "(água viva.)", "v": "h"}, {"t": " Água viva, que jorra de Deus. Enche-me, enche-me, sacia-me ", "v": "t"}, {"t": "(aleluia)", "v": "h"}, {"t": " (2x). SACIAME!", "v": "t"}], "c": [[140, "Am"], [144, "F"], [146, "G"], [150, "C"]]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
