('songs','s046','{"n": 460, "day": "sabado", "group": "", "title": "Canto das refeições", "st": [[{"r": [{"t": "ANTES:", "v": "m"}]}, {"r": [{"t": "O senhor abençoai esta nossa refeição.(BIS)", "v": "t"}], "c": [[0, "(C)"], [5, "F"], [13, "G"], [33, "C"]]}, {"r": [{"t": "Que hoje tem mais alegria (BIS)", "v": "t"}], "c": [[10, "F"], [21, "C"]]}, {"r": [{"t": "Com a tua, com a tua Com a tua companhia (BIS)", "v": "t"}], "c": [[7, "F"], [18, "C"], [25, "F"], [33, "G"], [42, "C"]]}], [{"r": [{"t": "Uns tem mas não podem, outros podem, mas não tem. Nós que temos e podemos, bendigamos ao Senhor dizendo: Amém!", "v": "m"}]}], [{"r": [{"t": "DEPOIS:", "v": "m"}]}, {"r": [{"t": "Ao senhor agradecemos, aleluia. O alimento que tivemos, aleluia. (BIS)", "v": "t"}], "c": [[0, "C"], [10, "G"], [26, "F"], [29, "C"], [34, "Am"], [49, "F"], [57, "G"], [66, "C"]]}, {"r": [{"t": "Por isso eu canto aleluia, aleluia, aleluia (BIS).", "v": "t"}], "c": [[14, "F"], [21, "C"], [30, "F"], [36, "G"], [39, "F"], [41, "C"]]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
('songs','s047','{"n": 470, "day": "sabado", "group": "", "title": "Companheiro e amigo", "st": [[{"r": [{"t": "Jesus Cristo é o caminho pra você sempre seguir, companheiro verdadeiro não me deixa desistir. Jesus Cristo é o amigo que nos dá a proteção, pros problemas dessa vida ele traz a soluçãoQue prazer é ter na vida eterna vida alegria e paz no coração uma certeza que essa riqueza é Jesus quem dá e essa é a razão. ", "v": "t"}, {"t": "do meu cantar", "v": "h"}, {"t": "(aleluia haaaa)/", "v": "m"}, {"t": "do meu louvar", "v": "h"}, {"t": "(aleluia haaaa)/", "v": "m"}, {"t": "do meu cantar", "v": "h"}, {"t": "(aleluia haaaa)/", "v": "m"}, {"t": "do meu louvar", "v": "h"}, {"t": "(aleluia haaaa)", "v": "m"}], "pre": ["(D) G D A Bm F#m G A (2x)", "G D A D (2x)", "G D (4x)"]}, {"r": [{"t": "Ho Aleluia , ho aleluia. Alegria e paz no coração, uma certeza que essa riqueza é jesus quem dá e essa é a razão. ", "v": "t"}, {"t": "do meu cantar", "v": "h"}, {"t": "(aleluia haaaa)/", "v": "m"}, {"t": "do meu louvar", "v": "h"}, {"t": "(aleluia haaaa)/", "v": "m"}, {"t": "do meu cantar", "v": "h"}, {"t": "(aleluia haaaa)/", "v": "m"}, {"t": "do meu louvar", "v": "h"}], "pre": ["G D A D (2x)", "G D (4x)"]}, {"r": [{"t": "Que prazer é ter na vida eterna vida alegria e paz no coração uma certeza que essa riqueza é Jesus quem dá e essa é a razão ", "v": "t"}, {"t": "do meu cantar ", "v": "h"}, {"t": "(aleluia haaaa)", "v": "m"}, {"t": " do meu louvar", "v": "h"}, {"t": "(aleluia haaaa)", "v": "m"}, {"t": "do meu cantar,", "v": "h"}, {"t": " (aleluia haaaa)", "v": "m"}, {"t": " do meu louvar", "v": "h"}]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
