('songs','s049','{"n": 490, "day": "sabado", "group": "", "title": "Só em ti viver", "st": [[{"r": [{"t": "As coisas que o mundo oferecia me Impediam de te encontrar, de ver que a vida é só em ti… Mas tu viestes e tocaste, bem no fundo do meu coração, me ensinaste a te amar. Oh! Jesus, recebe então a minha vida. Recebe as coisas que de ti me afastam, pois só em ti quero viver", "v": "t"}, {"t": ".", "v": "m"}], "pre": ["Intro: A Bm C#m E", "A Bm C#m Bm C#m Bm C#m E (2x)"]}, {"r": [{"t": "Oh! Jesus", "v": "h"}, {"t": " (meu Jesus) ", "v": "m"}, {"t": "recebe então a minha vida", "v": "h"}, {"t": " (vida) Recebe as coisas que de ti me afastam (eu te amo) ", "v": "m"}, {"t": "pois só em ti quero viver.", "v": "t"}], "pre": ["A Bm C#m F# Bm E A E (2x)"]}, {"r": [{"t": "Agora que meu coração é teu/ quero sempre te louvar / tua vida transbordar. Para que mais gente experimente Teu amor Nos transbordando, tua mão a nos tocar.", "v": "m"}], "pre": ["A Bm C#m Bm C#m Bm C#m E (2x)"]}, {"r": [{"t": "Oh! Jesus, recebe então a minha vida. Recebe as coisas que de ti me afastam, pois só em ti quero viver", "v": "t"}, {"t": ". ", "v": "m"}, {"t": "Oh! Jesus", "v": "h"}, {"t": " (meu Jesus) ", "v": "m"}, {"t": "recebe então a minha vida", "v": "h"}, {"t": " (vida) Recebe as coisas que de ti me afastam (eu te amo) ", "v": "m"}, {"t": "pois só em ti quero viver.", "v": "t"}], "pre": ["A Bm C#m F# Bm E A E (2x)"]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
('songs','s050','{"n": 500, "day": "sabado", "group": "", "title": "Alfa ômega", "st": [[{"r": [{"t": "Tu que estás assentado ÔÔÔÔ no trono. Sempre reinando, soberano. Anjos cantando ÔÔÔÔ homens louvando, Deus reunido com seu povo.", "v": "t"}], "pre": ["G C D C G C Am D (BIS)"]}], [{"r": [{"t": "Oh! Oh! Alfa, ômega, CRISTO, Filho, Oh, oh vem. Oh, oh vem, Senhor JESUS.(2x)", "v": "t"}], "c": [[0, "G"], [1, "B"], [4, "Em"], [8, "D"], [9, "C"], [14, "Em"], [14, "G"], [17, "C"], [21, "D"], [21, "G"]]}, {"r": [{"t": "Ansioso espero ÔÔÔÔ a tua volta. No grande dia, em que tu virás. Então subiremos ÔÔÔÔ contigo estaremos, para todo sempre, aleluia.", "v": "t"}], "pre": ["G C D C G C Am D (BIS)"]}, {"r": [{"t": "Maranata, CRISTO Filho, Mestre, Oh, oh vem. Oh oh vem, Senhor JESUS.", "v": "t"}], "c": [[0, "G"], [1, "B"], [3, "Em"], [7, "D"], [10, "C"], [11, "G"], [13, "Em"], [17, "C"], [18, "D"], [20, "G"]]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
('songs','s051','{"n": 510, "day": "sabado", "group": "", "title": "Só podia ser Jesus", "st": [[{"r": [{"t": "Minha cabeça rodava. No peito o coração doía. Sentia apodrecer por dentro ", "v": "t"}, {"t": "(o que?)", "v": "h"}, {"t": " Toda minha alegria. Sem forças no caminhar ", "v": "m"}, {"t": "(quase caindo)", "v": "h"}, {"t": " As trevas me perseguiam. E o ódio fazendo ", "v": "m"}, {"t": "horrooooor.", "v": "t"}, {"t": " Viver assim não podia.", "v": "m"}], "pre": ["G A D Bm G A D (2x) D7"]}, {"r": [{"t": "Então uma luz em mim brilhou, das trevas me libertou. Senti o Espírito de Deus. Tudo em mim se acendeu! ", "v": "t"}, {"t": "(Oh gloria a Deus)", "v": "h"}], "pre": ["G A D (2x)"]}, {"r": [{"t": "Mas só podia ser Jesus ↑ ", "v": "t"}, {"t": "(só, só, só) ", "v": "m"}, {"t": "Só podia ser Jesus (4x) ", "v": "h"}, {"t": "(BIS)", "v": "t"}], "c": [[0, "G"], [2, "A"], [4, "F#"], [7, "Bm"], [10, "G"], [13, "A"], [14, "G"], [17, "D"], [19, "G"], [21, "A"], [26, "D"]]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
