('songs','s053','{"n": 530, "day": "sabado", "group": "", "title": "Deus quero louvar-te", "st": [[{"r": [{"t": "Deus quero louvar-te", "v": "h"}, {"t": " (quero louvar-te) ", "v": "m"}, {"t": "quero adorar-te", "v": "h"}, {"t": " (quero adorar-te). ", "v": "m"}, {"t": "Quero te servir, quero transmitir Deus quero louvar-te . ", "v": "t"}, {"t": "Deus quero louvar-te", "v": "h"}, {"t": " (quero louvar-te) ", "v": "m"}, {"t": "quero adorar-te", "v": "h"}, {"t": " (quero adorar-te). ", "v": "m"}, {"t": "Sempre ao cantar eu só quero dar glórias ao meu Deus.", "v": "t"}], "c": [[0, "C"], [0, "D"], [0, "Em"]], "pre": ["G Em G Em C D G D (BIS)", "Em  C  Em  C  Em  C  D"]}, {"r": [{"t": "Eu vou caminhando, vivendo o amor. Erguendo os meus braços. Eu louvo ao senhor. Quero proclamá-lo no dia-a-dia, sempre cantando Glória, aleluia. Aleluuuuia.", "v": "t"}]}, {"r": [{"t": "REPETE", "v": "t"}]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
