('songs','s057','{"n": 570, "day": "sabado", "group": "", "title": "Vem louvar", "st": [[{"r": [{"t": "Aleluia aleluia aleluia ", "v": "m"}, {"t": "(vem louvar vem 4x)", "v": "h"}, {"t": " (BIS)", "v": "m"}], "c": [[0, "E"], [1, "A"], [4, "C#m"], [9, "B"]]}, {"r": [{"t": "Hoje é tempo de louvar a Deus, em nós agora habita o seu espírito, ", "v": "m"}, {"t": "então é só cantar e a Cristo exaltar, e sua glória encherá este lugar (BIS)", "v": "t"}], "c": [[0, "E"], [14, "A"], [26, "E"], [46, "A"], [59, "B"], [70, "A"], [81, "E"], [91, "A"], [99, "E"], [113, "A"], [120, "F#m"], [133, "B"]]}, {"r": [{"t": "Vem louvar, ", "v": "t"}, {"t": "Ó VEM LOUVAR,", "v": "m"}, {"t": " vem louvar ", "v": "t"}, {"t": "Ó VEM LOUVAR…", "v": "m"}], "c": [[0, "E"], [1, "A"], [4, "C#m"], [8, "B"]]}, {"r": [{"t": "Aleluia aleluia aleluia ", "v": "m"}, {"t": "(vem louvar vem 4x)", "v": "h"}, {"t": " (BIS)", "v": "m"}]}, {"r": [{"t": "No meio dos louvores Deus habita É seu prazer cumprir O que nos diz. ", "v": "m"}, {"t": "Então é só… ", "v": "t"}, {"t": "(REFRÃO)", "v": "m"}]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
('songs','s058','{"n": 580, "day": "sabado", "group": "", "title": "Calma", "st": [[{"r": [{"t": "Entregue tua cruz e fique do meu lado. Eu não deixarei você chegar rente ao chão. Calma, calma, estamos perto do Calvário. E eu que não sou de rezar, entreguei-me em tuas mãos, não foi em vão.", "v": "m"}], "c": [[0, "G"], [40, "C"], [123, "Am"], [128, "Bm"]]}, {"r": [{"t": "Calma, calma, estamos perto do Calvário. E foi assim, que Ele suportou a dor sempre do meu lado.", "v": "m"}], "c": [[0, "G"], [3, "C"]]}, {"r": [{"t": "E pude perceber, que naquele olhar, levava a multidão em seu coração.", "v": "m"}], "c": [[0, "Am"], [3, "Bm"]]}, {"r": [{"t": "Eu não deixarei, você chegar rente ao chão. Calma, calma, estamos perto do Calvário.", "v": "m"}], "c": [[0, "G"], [36, "C"]]}, {"r": [{"t": "E eu que não sou de rezar, entreguei-me em tuas mãos, não foi em vão. Eu não deixarei, você chegar rente ao chão, calma, calma, estamos perto do Calvário. E pude perceber, que naquele olhar, levava a multidão em seu coração.", "v": "m"}], "c": [[0, "Am"], [5, "Bm"], [70, "G"], [106, "C"], [155, "Am"], [186, "Bm"]]}, {"r": [{"t": "Com muita calma, calma. Calma calma.", "v": "m"}], "c": [[0, "G"]]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
('songs','s059','{"n": 590, "day": "sabado", "group": "", "title": "Santa paz", "st": [[{"r": [{"t": "Uma paz tão grande e diferente Veio pra ficar e para sempre Oh, aleluia, a vossa paz. Que maravilha poder cantar.", "v": "t"}], "pre": ["Intro: D G D G", "D G D G (BIS)"]}, {"r": [{"t": "Seja o hábito do coração essa paz que habita a vida agora irmão ", "v": "t"}, {"t": "(Tanta paz)", "v": "h"}, {"t": " Tanta paz, gloriosa paz que nos faz servindo a Deus em união.", "v": "t"}], "c": [[0, "Bm"], [5, "G"], [7, "A"], [8, "D"], [10, "A"], [14, "Bm"], [17, "G"], [19, "D"], [21, "A"], [23, "D"], [26, "(A)"]]}, {"r": [{"t": "Há uma flor no mundo ainda livre. Tua paz que vem e logo vai. Oh, aleluia, a vossa paz que maravilha a paz que vai", "v": "t"}], "pre": ["D G D G (BIS)"]}, {"r": [{"t": "Seja o hábito do coração essa paz que habita a vida agora irmão ", "v": "t"}, {"t": "(Tanta paz)", "v": "h"}, {"t": " Tanta paz, gloriosa paz /que nos faz servindo a Deus em união.(BIS)", "v": "t"}], "c": [[0, ".Bm"], [5, "G"], [7, "A"], [9, "D"], [11, "A"], [14, "Bm"], [18, "G"], [20, "D"], [22, "A"], [25, "D"]]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
('songs','s060','{"n": 600, "day": "sabado", "group": "", "title": "Aprendiz", "st": [[{"r": [{"t": "Tchuru tchurururu(3x)", "v": "t"}], "c": [[0, "G"], [2, "Am"], [7, "D"], [8, "G"], [10, "D"], [13, "(G7)"]]}, {"r": [{"t": "Sei que vem um dia, sim virá viver a luz. E Deus há de nos preencher com o amor. Homem, bem ou mal, um ser, também qualquer, de Deus. Render-se-á por fim, a plena paz ", "v": "m"}, {"t": "Minha Alma de pecador, amador Natureza de infringir, de errar. Quer se redimir, ser feliz Aprendiz quer buscar. O brilho das manhãs do luar de entender, criatura ao criador. Retornar, estender a mão. Ser cristão todo irmão para amar", "v": "h"}]}, {"r": [{"t": "Sim perfeito sei eu não sou também ", "v": "t"}, {"t": "(eu não sou também)", "v": "h"}, {"t": " Não me leve a mal, “tô tentando”. Será sempre assim ", "v": "t"}, {"t": "(sempre assim)", "v": "h"}, {"t": " Estou aprendendo a amar.", "v": "t"}], "c": [[0, "C"], [2, "C"], [4, "G"], [6, "F"], [8, "E"], [10, "Am"], [14, "D"], [17, "G"], [20, "G7"]]}, {"r": [{"t": "(Repete cantando a primeira parte ao mesmo tempo).", "v": "m"}]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
('songs','s061','{"n": 610, "day": "sabado", "group": "", "title": "Abraço de pai", "st": [[{"r": [{"t": "Quanto eu esperei/Ansioso queria te ver/E te falar o que há em mim/Já não podia me conter/Me decidi, Senhor/Hoje quero rasgar meu viver/E te mostrar meu coração,", "v": "t"}, {"t": "/", "v": "m"}, {"t": "Tudo o que tenho e sou/E por mais que me falem, não vou desistir", "v": "t"}, {"t": "/", "v": "m"}, {"t": "Eu sei que nada sou ! Por isso estou aqui", "v": "t"}, {"t": "/", "v": "m"}, {"t": "Mas eu sei que o amor que o Senhor tem por mim", "v": "t"}, {"t": "/", "v": "m"}, {"t": "É muito mais que o meu, sou gota/ derramada no mar/Quanto tempo também o Senhor me esperou", "v": "t"}, {"t": "/", "v": "m"}, {"t": "Nas tardes encontrou saudade em meu lugar/Mas ao me ver na estrada ao longe voltar", "v": "t"}, {"t": "/", "v": "m"}, {"t": "Num salto se alegrou e foi correndo me encontrar/E não me perguntou nem por onde eu andei/Dos bens que eu gastei, mais nada me restou/Mas olhando em meus olhos somente me amou", "v": "t"}, {"t": "/", "v": "m"}, {"t": "E ao me beijar,", "v": "t"}, {"t": "/", "v": "m"}, {"t": "Me acolheu/num abraço de pai.", "v": "t"}], "c": [[0, "E"], [18, "C#m"], [27, "G#m"], [42, "F#m"], [54, "G#m"], [61, "A"], [68, "F#m"], [91, "E"], [108, "C#m"], [119, "G#m"], [138, "F#"], [150, "G#m"], [156, "A"], [163, "F#m"], [182, "D"], [183, "B"], [192, "E"], [210, "C#m"], [228, "F#m"], [253, "B"], [273, "E"], [299, "C#m"], [318, "F#m"], [340, "B"], [365, "B"], [365, "E"], [370, "E"], [390, "C#m"], [409, "F#m"], [432, "B"], [456, "E"], [477, "C#m"], [492, "F#m"], [511, "B"], [537, "B"], [537, "E"], [546, "E"], [566, "C#m"], [582, "F#m"], [610, "B"], [626, "E"], [652, "C#m"], [666, "F#m"], [675, "A"], [682, "F#m"], [687, "B"], [707, "E"], [709, "(B)"]]}]], "tail": [], "hist": [], "at": 0, "by": null}'::jsonb),
